export type ProjectCategory = 'Full Stack' | 'AI & Vision' | 'Robotics / IoT' | 'Mobile';

export interface Project {
  id: string;
  title: string;
  subtitle: string;
  description: string;
  longDescription: string;
  category: ProjectCategory;
  tags: string[];
  image: string;
  liveUrl: string;
  githubUrl?: string;
  featured: boolean;
  metrics: string;
  features: string[];
  techStack: string[];
}

export interface Certificate {
  id: string;
  title: string;
  issuer: string;
  date: string;
  credentialUrl?: string;
  badge: string;
  skillsCovered: string[];
  imageUrl?: string;
  pdfUrl?: string;
}

export interface SkillItem {
  name: string;
  level: number;
  iconName?: string;
  highlight?: boolean;
}

export interface SkillCategory {
  category: string;
  description: string;
  skills: SkillItem[];
}

export interface TimelineItem {
  id: string;
  period: string;
  role: string;
  organization: string;
  location: string;
  description: string;
  highlights: string[];
  type: 'education' | 'leadership' | 'experience';
}

export interface ServiceItem {
  id: string;
  title: string;
  description: string;
  icon: string;
  tags: string[];
  features: string[];
}

export interface PersonalInfo {
  name: string;
  handle: string;
  titles: string[];
  bio: string;
  longBio: string;
  education: string;
  location: string;
  email: string;
  socials: {
    instagram: string;
    github: string;
    linkedin: string;
  };
  resumeUrl: string;
  avatarUrl: string;
  livePortfolioUrl: string;
  stats: { label: string; value: string }[];
}

export interface PortfolioData {
  personal: PersonalInfo;
  projects: Project[];
  certificates: Certificate[];
  skills: SkillCategory[];
  services: ServiceItem[];
  timeline: TimelineItem[];
}

